package org.jsoup.nodes;

import org.jsoup.parser.Parser;
import org.junit.Test;
import org.mockito.Mockito;

import java.io.IOException;
import static org.hamcrest.CoreMatchers.is;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class CommentTest {

	@Test
	public void CommentConstructorTest() {
		Comment comment = new Comment("test");
		assertNotNull(comment);
		assertThat(comment.getData(), is("test"));
	}

	@Test
	public void nodeNameTest() {
		Comment comment = new Comment("test");
		assertThat(comment.nodeName(), is("#comment"));
	}

	@Test
	public void getDataTest() {
		Comment comment = new Comment("test");
		assertThat(comment.getData(), is("test"));
	}

	@Test
	public void setDataTest() {
		Comment comment = new Comment("test");
		comment.setData("newData");
		assertThat(comment.getData(), is("newData"));
	}

	@Test
	public void outerHtmlHeadTest() throws IOException {
		Comment comment = new Comment("test");
		Document.OutputSettings outputSettings = new Document.OutputSettings();

		StringBuilder accum = new StringBuilder();
		comment.outerHtmlHead(accum, 0, outputSettings);

		assertThat(accum.toString(), is("<!--test-->"));
	}

	@Test
	public void outerHtmlTailTest() {
		Document.OutputSettings outputSettings = new Document.OutputSettings();

		Comment comment = new Comment("test");
		StringBuilder accum = new StringBuilder();
		comment.outerHtmlTail(accum, 0, outputSettings);

		assertThat(accum.toString(), is(""));
	}

	@Test
	public void toStringTest() {
		Comment comment = new Comment("test");
		assertTrue(comment.toString().contains("test"));
	}

	@Test
	public void cloneTest() {
		Comment comment = new Comment("test");
		Comment copy = comment.clone();

		assertTrue(comment != copy);
		assertTrue(comment.getClass() == copy.getClass());
		assertTrue(comment.equals(copy));
	}

	@Test
	public void isXmlDeclarationTest() {
		Comment comment = new Comment("test");
		assertTrue(!comment.isXmlDeclaration());
	}

	@Test
	public void asXmlDeclarationTest() {
		Comment comment = new Comment("test");
		assertTrue(comment.asXmlDeclaration() == null);
	}
}
